\title{A Tight $\Theta(n^{2w})$ Bound for Strict Alternating Cycles\\ in Width-$w$ Posets}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
For a fixed integer width $w \ge 2$, we study the maximum number of \emph{strict alternating cycles} that an $n$-element partially ordered set of width $w$ can contain. Strict alternating cycles are the irreducible obstructions of poset dimension theory: a cyclic family of incomparable pairs in which each lower vertex dominates exactly one upper vertex---its cyclic successor. A standard counting argument (each cycle of length $k$ is pinned by its $2k$ vertices, and Dilworth's theorem caps the length at $w$) yields an upper bound of $O(n^{2w})$. The matching lower bound is the difficult direction. We resolve it with an explicit construction, the \emph{blown-up crown} $\Crown(w,m)$, obtained from the standard example crown $S_w$ by replacing each of its $2w$ vertices with a chain of $m$ clones. We prove that this poset has exactly $2wm$ elements, has width exactly $w$ (the load-bearing fact, certified by an explicit column-folding injection), and carries at least $m^{2w}$ distinct strict alternating cycles. Setting $n = 2wm$ gives a width-$w$ poset on $n$ points with at least $(2w)^{-2w} n^{2w}$ strict alternating cycles, establishing that the maximum is $\Theta(n^{2w})$. All results have been formally verified.
\end{abstract}

\section{Introduction}

\subsection{Background}
A \emph{partially ordered set} (poset) is a pair $(P, \le)$ with $\le$ reflexive, antisymmetric, and transitive. Elements $x, y$ are \emph{comparable} if $x \le y$ or $y \le x$, and \emph{incomparable} ($x \parallel y$) otherwise. Quantifying incomparability is the theme of \emph{order dimension theory}, initiated by Dushnik and Miller and developed by Trotter. The \emph{dimension} of a poset is the least number of linear extensions whose intersection recovers $\le$; the combinatorial obstruction to small dimension is the \emph{strict alternating cycle}. The canonical dimension-forcing examples are the \emph{crowns} (standard examples) $S_w$, of $2w$ elements and dimension exactly $w$. By Dilworth's theorem the \emph{width} of $P$ equals both the maximum antichain size and the minimum number of covering chains.

\subsection{The extremal question}
Fix $w \ge 2$ and let $A_w(n)$ be the maximum number of strict alternating cycles in an $n$-element width-$w$ poset (cycles counted as indexed cyclic families). A counting argument gives the classical upper bound $A_w(n) = O(n^{2w})$: a length-$k$ cycle is determined by its $2k$ vertices, and its lower vertices form an antichain, so $k \le w$. We prove the matching lower bound.

\begin{theorem}[Main]
For every fixed $w \ge 2$, $A_w(n) = \Theta(n^{2w})$. Explicitly, for $n$ divisible by $2w$ there is a width-$w$ poset on $n$ elements with at least $(2w)^{-2w} n^{2w}$ strict alternating cycles.
\end{theorem}

\section{Preliminaries}
Throughout $w \ge 2$, $m \ge 1$, and column indices in $\{0,\dots,w-1\}$ are taken modulo $w$; $i+1$ denotes the cyclic successor.

\begin{definition}[Antichain, width]
$A \subseteq P$ is an \emph{antichain} if distinct elements of $A$ are incomparable. The \emph{width} is $\width(P) = \max\{|A| : A \text{ an antichain}\}$.
\end{definition}

\begin{definition}[Strict alternating cycle]
A family $p : \{0,\dots,w-1\} \to P \times P$, $p(i) = (x_i,y_i)$, is a \emph{strict alternating cycle} if
\[
\textbf{(SAC1)}\quad \forall i,j:\ x_i \le y_j \iff j = i+1 \pmod w, \qquad
\textbf{(SAC2)}\quad \forall i:\ y_i \not\le x_i.
\]
Since $i \ne i+1$ for $w \ge 2$, (SAC1) forces $x_i \not\le y_i$; with (SAC2) each pair $(x_i,y_i)$ is incomparable.
\end{definition}

\section{The blown-up crown}

\begin{definition}[Carrier]
$\Crown(w,m)$ has elements $x = (\col,\side,\idx)$ with $\col \in \{0,\dots,w-1\}$, $\side \in \{\mathtt a, \mathtt b\}$ ($\mathtt a$ lower, $\mathtt b$ upper), $\idx \in \{0,\dots,m-1\}$. Write $a(i,j) = (i,\mathtt a,j)$, $b(i,j) = (i,\mathtt b,j)$.
\end{definition}

\begin{definition}[Order]
$x \le y$ iff either
\begin{itemize}[nosep]
\item \emph{(chain rule)} $x.\side = y.\side$, $x.\col = y.\col$, $x.\idx \le y.\idx$; or
\item \emph{(cross rule)} $x.\side = \mathtt a$, $y.\side = \mathtt b$, $y.\col = x.\col + 1 \pmod w$.
\end{itemize}
The cross rule is one-directional ($\mathtt a \to \mathtt b$) and index-free.
\end{definition}

\begin{proposition}
$(\Crown(w,m), \le)$ is a partial order.
\end{proposition}
\begin{proof}[Proof sketch]
Reflexivity: chain rule with equal indices. Transitivity: chain$\circ$chain stays in a stack; chain$\circ$cross and cross$\circ$chain remain single cross steps; cross$\circ$cross is impossible (a cross step ends on side $\mathtt b$ but must start on $\mathtt a$). Antisymmetry: a cross step in either direction is incompatible with its reverse, so both relations are chain rules, forcing equal side/column and equal indices. The one-directional cross orientation is what secures antisymmetry.
\end{proof}

\begin{theorem}[Cardinality]
$\#\,\Crown(w,m) = 2wm$.
\end{theorem}
\begin{proof}
$x \mapsto (x.\col, x.\side, x.\idx)$ is a bijection onto a product of sizes $w$, $2$, $m$.
\end{proof}

\section{Width is exactly $w$}

\begin{definition}[Column folding]
$\fold : \Crown(w,m) \to \{0,\dots,w-1\}$ (modulo $w$),
\[
\fold(x) = \begin{cases} x.\col & x.\side = \mathtt b,\\ x.\col + 1 & x.\side = \mathtt a.\end{cases}
\]
A conflicting cross pair $a(i,\cdot) \le b(i+1,\cdot)$ has both endpoints folding to $i+1$.
\end{definition}

\begin{lemma}[Fold is injective on antichains]
If $A$ is an antichain then $\fold\!\restriction_A$ is injective.
\end{lemma}
\begin{proof}[Proof sketch]
Suppose $x \ne y$ in $A$ with $\fold(x) = \fold(y)$. If $x,y$ share a side, then $x.\col = y.\col$, so they lie in one stack and are chain-comparable. If they have opposite sides, say $x.\side = \mathtt a$, $y.\side = \mathtt b$, then $y.\col = x.\col + 1$, i.e.\ $x \le y$ by the cross rule. Either way they are comparable, contradicting $A$ antichain.
\end{proof}

\begin{theorem}[Width]
$\width(\Crown(w,m)) = w$.
\end{theorem}
\begin{proof}
\emph{Upper:} any antichain injects via $\fold$ into a $w$-element set, so $\width \le w$. \emph{Lower:} $\{a(0,0),\dots,a(w-1,0)\}$ is an antichain of size $w$ (distinct elements share neither column for the chain rule nor opposite sides for the cross rule).
\end{proof}

\section{Counting strict alternating cycles}

\begin{definition}[Cycle family]
For $u,v : \{0,\dots,w-1\} \to \{0,\dots,m-1\}$,
\[
\cyc(u,v)(t) = \big(a(t,u(t)),\ b(t,v(t))\big).
\]
\end{definition}

\begin{theorem}[Each family is a strict alternating cycle]
For all $u,v$, $\cyc(u,v)$ satisfies (SAC1) and (SAC2).
\end{theorem}
\begin{proof}[Proof sketch]
With $x_t = a(t,u(t))$, $y_s = b(s,v(s))$: $x_t \le y_s$ only via the cross rule (opposite sides), which fires iff $s = t+1 \pmod w$, giving (SAC1). For (SAC2), $y_t \le x_t$ would need the chain rule (impossible, opposite sides) or a cross rule with $x_t$ on side $\mathtt b$ (impossible).
\end{proof}

\begin{theorem}[Injectivity]
$(u,v) \mapsto \cyc(u,v)$ is injective.
\end{theorem}
\begin{proof}
Equality of families forces $a(t,u(t)) = a(t,u'(t))$ and $b(t,v(t)) = b(t,v'(t))$ for all $t$, hence $u = u'$ and $v = v'$.
\end{proof}

\begin{corollary}[Cycle count]
$\Crown(w,m)$ contains at least $m^{2w}$ distinct strict alternating cycles.
\end{corollary}
\begin{proof}
$m^w$ choices for $u$ times $m^w$ for $v$, each giving a distinct cycle.
\end{proof}

\section{The asymptotic lower bound}

\begin{theorem}[Main lower bound]
For fixed $w \ge 2$ and any $m \ge 1$, $\Crown(w,m)$ has width $w$, $n = 2wm$ elements, and at least
\[
m^{2w} = \left(\frac{n}{2w}\right)^{2w} = \frac{1}{(2w)^{2w}}\, n^{2w}
\]
strict alternating cycles. With the classical $A_w(n) = O(n^{2w})$, this gives $A_w(n) = \Theta(n^{2w})$.
\end{theorem}
\begin{proof}
Combine the width, cardinality, and cycle-count results and substitute $m = n/(2w)$; for general $n$ pass to the largest multiple of $2w$ below $n$, changing the bound by a constant factor.
\end{proof}

\section{Algorithms}

\paragraph{Enumeration.} Iterate over all $u$ and $v$ in $\{0,\dots,w-1\} \to \{0,\dots,m-1\}$ and emit $t \mapsto (a(t,u(t)), b(t,v(t)))$. Time $\Theta(w\,m^{2w})$, realizing the count constructively.

\paragraph{Width certification.} Given an antichain $A$, compute $\fold$ on each element; the values are distinct (Lemma) and lie in a $w$-element set, so $|A| \le w$. The all-$a$ set certifies $\width \ge w$.

\section{Applications}
Strict alternating cycles are the obstructions forcing poset dimension up; the blown-up crown shows their density under fixed width follows a sharp power law. The result is a matching lower bound for a Tur\'an-type extremal problem. The width computation is a Dilworth/Mirsky antichain bound made explicit by folding. Incomparabilities and cycles model scheduling conflicts and cyclic preference paradoxes.

\section{Discussion}
The decisive choice is inflating vertices into \emph{chains}, not antichains: chains contribute nothing to antichains, so width is preserved; the cross relations and the folding map cut the naive $2w$ chain bound to the true width $w$. Counting indexed cyclic families over-counts geometric cycles by at most a factor $w$, not affecting the $\Theta(n^{2w})$ order. The count $m^{2w}$ is a genuine injective family, and the structure is a verified width-$w$ partial order.

\section{Future directions}

\begin{conjecture}[Sharp constant]
$\lim_{n\to\infty} M_w(n)/n^{2w}$ exists and equals $c_w^\* = 1/((2w)^{2w} w)$, where $M_w(n)$ counts cycles up to rotation. Equal chain lengths maximize $\prod m_i$ by AM--GM, pinning the constant.
\end{conjecture}

\begin{conjecture}[Length spectrum]
For fixed $w$, the number of strict alternating cycles of length exactly $k$ is $\Theta(n^{2k})$ for $2 \le k \le w$ and $0$ for $k > w$ (Dilworth forbids longer cycles).
\end{conjecture}

\begin{conjecture}[Dimension transfer]
$\Crown(w,m)$ has order dimension exactly $w$ for all $m \ge 1$; fattening a vertex into a chain is retract-stable, and $S_w$ embeds as the all-clone-$0$ sub-poset.
\end{conjecture}

\begin{conjecture}[Tur\'an-type dual]
Among $n$-element width-$w$ posets with no strict alternating cycle of length $w$, the maximum number of incomparable pairs is $o(n^2)$.
\end{conjecture}

\section{Conclusion}
The maximum number of strict alternating cycles in an $n$-element width-$w$ poset is $\Theta(n^{2w})$. The hard lower bound is realized by the blown-up crown $\Crown(w,m)$, a verified width-$w$ partial order on $2wm$ points with at least $m^{2w}$ strict alternating cycles, the keystone being width preservation under chain inflation via column folding.

\end{document}

