function fold(w, x):           # x = (col, side, idx)
    if x.side == b:  return x.col
    else:            return (x.col + 1) mod w

function certify_width_upper_bound(w, antichain A):
    values <- [ fold(w, x) for x in A ]
    assert all values distinct          # Lemma: fold injective on antichains
    assert every value in {0..w-1}
    return |A| <= w                      # since image has <= w elements

function width_lower_bound(w, m):
    A <- { (i, a, 0) : i in 0..w-1 }     # all-lower antichain
    assert A is an antichain and |A| = w
    return w
